package com.example.southindianplanner;
import android.content.*;import android.app.*;import android.os.*;
public class ReminderReceiver extends BroadcastReceiver { public void onReceive(Context c,Intent i){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)n.createNotificationChannel(new NotificationChannel("meal","Meal reminders",NotificationManager.IMPORTANCE_DEFAULT));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"meal"):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Tomorrow's cooking plan").setContentText("Open South Indian Meal Planner to check tomorrow's meals and groceries.").setAutoCancel(true);n.notify(1,b.build());} }
